// Supertype unions
export type Statement =
	| SimpleStatements
	| CompoundStatement
	| IfStatement
	| ForStatement
	| WhileStatement
	| TryStatement
	| WithStatement
	| FunctionDefinition
	| ClassDefinition
	| DecoratedDefinition
	| MatchStatement;

